Here's one way to implement a queue using two stacks in Python:
```
class Stack:
    def __init__(self):
        self.items = []

    def push(self, item):
        self.items.append(item)

    def pop(self):
        if len(self.items) == 0:
            raise IndexError('Stack is empty')
        return self.items.pop()

class Queue:
    def __init__(self):
        self.in_stack = Stack()
        self.out_stack = Stack()

    def enqueue(self, item):
        self.in_stack.push(item)

    def dequeue(self):
        return self.out_stack.pop()

    def empty(self):
        if len(self.in_stack) == 0 and len(self.out_stack) == 0:
            return True
        return False
```
